                    ]
                )
                input[1] = true
                input[2] = false
                input[3] = false
                """
            }

        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("Bacteroides fragilis genome - stub") {
        options "-stub"
        when {

            params {
                outdir = "test"
            }

            workflow {
                """
                input[0] = channel.of(
                    [
                        [ id: 'test' ],
