                    ]
                )
                input[1] = true
                input[2] = true
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    path(workflow.out.dict[0][1]).readLines()[0],
                    workflow.out.reference,
                    workflow.out.fai,
                    workflow.out.sizes,
                    workflow.out.sequence_description
                ).match() }
            )
        }
    }
}

